import 'package:flutter/material.dart';
import 'islami_kissalar.dart';

/// Islam tarihinden 20 kissa (Blok 6: Sahabe hayati, 2. bolum)
const List<Kissa> kissalar6 = [
  Kissa(baslik: 'Hz. Ebubekir (r.a.) ve Siddiklik', kaynak: 'Buhari, Fedail, 3', metin: 'Peygamberimiz (s.a.v.) Isra ve Mirac olayini anlattiginda, Kureysliler sasirdi. "Bu kadar kisa zamanda Mescid-i Aksa`ya nasil gidip geldin?" dediler. Hz. Ebubekir (r.a.) olayi duydugunda hic tereddut etmedi: "O soylediyse dogrudur" dedi. O gunden sonra "Siddik" unvanini aldi. Siddiklik, sorgusuz iman degil; Peygamberimizin (s.a.v.) dogruluguna tam guvenmekti. Vefatina kadar hicbir tereddut gostermedi.', hisse: 'Iman, suphe degil; teslimiyettir. Siddik olmak, Peygamberimize (s.a.v.) kayitsiz sartsiz guvenmektir.', anahtarKelimeler: ['Siddik', 'Isra', 'Iman'], ikon: Icons.verified_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Hz. Omer (r.a.) ve Adalet Terazisi', kaynak: 'Ibn Sad, Tabakat', metin: 'Hz. Omer (r.a.) bir gun carsiyi dolasirken bir deve gordu. Deve zayif kalmis, sahibi yukleri agir yuklemisti. Hz. Omer (r.a.) hemen deve sahibini buldu: "Bu hayvana niye yukledin? Hesabini Rabbine nasil vereceksin?" dedi. Adamin serzenisine kulak asmadi: "Sen bu hayvanin hakkini yiyorsun. Haksizlik yapmanin bedeli buyuktur" dedi. Adama ceza verdi, deveyi azat etti.', hisse: 'Adalet, hayvanlara bile uzanan bir sorumluluktur. Kul, Rabbine hesap verecegini bilirse, her canliya iyi davranir.', anahtarKelimeler: ['Adalet', 'Hayvan', 'Sorumluluk'], ikon: Icons.balance_rounded, renk: Color(0xFFC9A961)),
  Kissa(baslik: 'Hz. Osman (r.a.) ve Hayâ', kaynak: 'Tirmizi, Menakib, 18', metin: 'Hz. Osman (r.a.), Peygamberimizin (s.a.v.) iki kizini da nikahina aldigi icin "Zinnureyn" (iki nur sahibi) unvanini aldi. Hayâ sahibiydi; hicbir zaman cirilciplak yikanmadi, eve girdiginde bile elbisesini duzeltirdi. Melekler ondan haya ederdi. Bir gun bir adam ona bakti, o gozlerini yere indirdi. "Neden bakmiyorsun?" dediler. "Goz zinasindan korkarim" dedi.', hisse: 'Hayâ, imanin susudur. Utangac olan, edepli olur; edepli olan, Allaha yakin olur.', anahtarKelimeler: ['Haya', 'Edeb', 'Iffet'], ikon: Icons.water_drop_rounded, renk: Color(0xFF2FAE7F)),
  Kissa(baslik: 'Hz. Ali (r.a.) ve Ilm-i Ledun', kaynak: 'Buhari, Fedail, 20', metin: 'Hz. Ali (r.a.), Peygamberimizin (s.a.v.) yaninda buyudu. Bir gun bir adam ona: "Ey Ali, ilmin kapisi oldugunu soyluyorlar. Bize bir sey ogret" dedi. Hz. Ali (r.a.): "Sen kalbini ilme acarsan, ben sana ogretirim. Once ogrenmeye niyet, sonra sabir, sonra amel gerekir. Sabirsiz ogrenci, ilmin lezzetini alamaz" dedi. Adam kalbini acti, Hz. Ali (r.a.) ona bir yil ders verdi. Adam buyuk alim oldu.', hisse: 'Ilim, ogrenmeye hazir kalp ister. Sabir, ogrenmenin ilk adimidir.', anahtarKelimeler: ['Ali', 'Ilim', 'Sabir'], ikon: Icons.school_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Hz. Hatice (r.anha) ve Ticaret Ahlaki', kaynak: 'Ibn Hisam, Siret', metin: 'Hz. Hatice (r.anha), Mekke`nin en zengin tuccariydi. Kervanlarini guvenilir insanlarla calistirirdi. Bir gun Peygamberimiz (s.a.v.)`in guvenilirligini duydu, ona kervanini teslim etti. Peygamberimiz (s.a.v.) kervani goturdu, satti, kar etti. Hz. Hatice (r.anha) beklediginden fazla kar gordu. "Bu adam guvenilir" dedi. Sonra onunla evlendi. O gunden sonra butun malini Islam yolunda harcadi.', hisse: 'Ticaret ahlaki, guvenilirlikle baslar. Guvenilir kul, Rabb katinda da yucelir.', anahtarKelimeler: ['Hatice', 'Ticaret', 'Guven'], ikon: Icons.trending_up_rounded, renk: Color(0xFFC9A961)),
  Kissa(baslik: 'Hz. Fatima (r.anha) ve Sabir', kaynak: 'Tirmizi, Menakib, 60', metin: 'Hz. Fatima (r.anha), Peygamberimizin (s.a.v.) kiziydi. Cocuklarini buyuturken el degirmeni cevirdi, ekmek pisirdi, su tasidi. Bir gun Peygamberimiz (s.a.v.) onun yorgun halini gordu, bir hizmetci teklif etti. Hz. Fatima (r.anha): "Babacigim, ben Rabbime kul olmayi secmisim. Hizmetci degil, dua ogret bana" dedi. Peygamberimiz (s.a.v.) ona sabah-aksam tesbih ogretti. Hz. Fatima (r.anha) o gun bu tesbihi hayati boyunca birakmadi.', hisse: 'Sabir, zorluga dayanmak degil; zahmetle Rabbe yaklasmaktir.', anahtarKelimeler: ['Fatima', 'Sabir', 'Tesbih'], ikon: Icons.spa_rounded, renk: Color(0xFF2FAE7F)),
  Kissa(baslik: 'Hz. Aise (r.anha) ve Ilmi Muzakere', kaynak: 'Buhari, Fedailul Kuran, 3', metin: 'Hz. Aise (r.anha), hadis ve fikih ilminde essizdi. Bir gun sahabe toplanmis bir meselede ihtilafa dustuler. Hz. Aise (r.anha) sustu, onlari dinledi. Sonra: "Sizin dediklerinizin hicbiri Kuran`a uygun degil. Ayet su: ..." dedi. Herkes saskin kaldi. O gunden sonra sahabe zor sorularini ona sordu. Hz. Aise (r.anha) yirmi iki yasinda dul kaldi; elli yil boyunca ilim ogretti.', hisse: 'Ilim, cinsiyet tanimaz. Kadin, Islam tarihinin en buyuk muallimlerinden olabilir.', anahtarKelimeler: ['Aise', 'Ilim', 'Hadis'], ikon: Icons.book_rounded, renk: Color(0xFFC9A961)),
  Kissa(baslik: 'Bilal (r.a.) ve Ezan Sesi', kaynak: 'Ibn Mace, Ezan, 1', metin: 'Bilal (r.a.), koleydi; iskence altinda "Ehad! Ehad!" derdi. Azat edildikten sonra Islam`in ilk ezanini okudu. Sesi, Medine`nin butun sokaklarina yayildi. Bir gun bir yabanci onu dinledi ve agladi: "Bu ses, kalbime isliyor" dedi. Bilal (r.a.), Peygamberimizin (s.a.v.) vefatindan sonra ezan okumayi birakti. Yillarca susdu. Bir gun Hz. Omer (r.a.) onu davet etti. Bilal (r.a.) ezan okudu. Butun sahabe agladi.', hisse: 'Ezan, imanin sesidir. Onu okuyan, Rabbe cagirir; onu duyan, Rabbe kosar.', anahtarKelimeler: ['Bilal', 'Ezan', 'Iman'], ikon: Icons.campaign_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Selman-i Farisi (r.a.) ve Fetih Fikri', kaynak: 'Ibn Ishak, Siret', metin: 'Hendek savasinda muslumanlar kusatildi. Selman-i Farisi (r.a.) Iran`dan gelmisti, savas taktiklerini iyi bilirdi. "Medine`nin cevresine hendek kazalim" dedi. Peygamberimiz (s.a.v.) kabul etti. Sahabiler bir ay boyunca gece gunduz hendek kazdi. Selman (r.a.) digerlerinden daha cok calisti. Hendek, dusman ordusunu durdurdu. Firtina cikti, dusman dagildi. Muslumanlar kurtuldu.', hisse: 'Yabanci olmak, faydali olmaya engel degildir. Fikir, millet tanimaz.', anahtarKelimeler: ['Selman', 'Hendek', 'Fetih'], ikon: Icons.foundation_rounded, renk: Color(0xFF2FAE7F)),
  Kissa(baslik: 'Musab bin Umeyr (r.a.) ve Muallimlik', kaynak: 'Ibn Hisam, Siret', metin: 'Musab bin Umeyr (r.a.), Mekke`nin en zengin gencidir. Islam`a girince annesi butun malini aldi. Yoksul kaldi. Peygamberimiz (s.a.v.) onu Medine`ye muallim olarak gonderdi. Musab (r.a.) bir yil icinde kavmin yarisini musluman yapti. Usame bin Zeyd (r.a.), onun talebesi oldu. Bir gun biri ona: "Zenginken simdi fakirsin, pisman misin?" dedi. Musab (r.a.): "Ben iman zenginligini kazandim, mal zenginligini degil" dedi.', hisse: 'Gercek zenginlik, imandir. Mal gider, iman kalir.', anahtarKelimeler: ['Musab', 'Muallim', 'Zenginlik'], ikon: Icons.school_rounded, renk: Color(0xFFC9A961)),
  Kissa(baslik: 'Sad bin Muaz (r.a.) ve Kavmi', kaynak: 'Ibn Hisam, Siret', metin: 'Sad bin Muaz (r.a.), Medine`nin en buyuk kabilesi Evs`in lideriydi. Musab (r.a.) ona teblig etti, o da musluman oldu. Kabile mescide toplandi. Sad (r.a.): "Ey kavmim, ben musluman oldum. Siz de musluman olun. Yoksa ben sizinle konusmam" dedi. Bir gun icinde butun kabile musluman oldu. Sad (r.a.), Uhud`da sehid edildi. Ars, onun gelisiyle titredi.', hisse: 'Lider, kavmin aynasidir. Lider iman ederse, kavim de eder.', anahtarKelimeler: ['Sad', 'Kavim', 'Sehadet'], ikon: Icons.people_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Zeyd bin Harise (r.a.) ve Vefa', kaynak: 'Tirmizi, Menakib, 40', metin: 'Zeyd bin Harise (r.a.), Peygamberimizin (s.a.v.) evinde buyudu. Babasi onu almaya geldiginde: "Ben senin yanindan ayrilmam" dedi. Peygamberimiz (s.a.v.): "O halde sen ozgursun, istersen git" buyurdu. Zeyd (r.a.) gitmedi. Mute`de ordunun komutani oldu, sehid edildi. Vefat haberi geldiginde Peygamberimiz (s.a.v.) agladi: "Zeyd, Rabbine kavustu" buyurdu.', hisse: 'Vefa, sozde durmaktir. Zeyd (r.a.), Rabbine ve Peygamberine sadik kaldi.', anahtarKelimeler: ['Zeyd', 'Vefa', 'Sehadet'], ikon: Icons.handshake_rounded, renk: Color(0xFF2FAE7F)),
  Kissa(baslik: 'Abdullah bin Mesud (r.a.) ve Kuran', kaynak: 'Buhari, Fedail, 24', metin: 'Abdullah bin Mesud (r.a.), Mekke`nin fakir cobanidir. Peygamberimiz (s.a.v.) ona bir gun: "Bana Kur`an oku" buyurdu. O: "Ya Resulullah, Kur`an sana indi, ben mi okuyayim?" dedi. Peygamberimiz (s.a.v.): "Ben Kur`an`i baskasindan dinlemeyi severim" buyurdu. Abdullah (r.a.) Nisa suresini okudu. Bir yere geldiginde Peygamberimiz (s.a.v.)`in gozleri yasardi: "Yeter" buyurdu. Abdullah (r.a.) o gunden sonra Kuran muallimi oldu.', hisse: 'Kuran okumak, Rabbe konusmaktir. Onu okuyan, kalbi titrer.', anahtarKelimeler: ['Abdullah', 'Kuran', 'Ilim'], ikon: Icons.menu_book_rounded, renk: Color(0xFFC9A961)),
  Kissa(baslik: 'Hz. Bilal (r.a.) ve Hicret', kaynak: 'Ibn Mace, Ezan, 1', metin: 'Bilal (r.a.), koleyken iskence edildi. Hz. Ebubekir (r.a.) onu satin alip azat etti. Bilal (r.a.), Habesistan`a hicret etti, sonra Medine`ye dondu. Medine`de Islam`in ilk ezanini okudu. Bir gun biri ona: "Sen koleyken azat edildin, ama hala hizmet ediyorsun, niye?" dedi. Bilal (r.a.): "Ben Rabbime kulluk etmeyi secmisim. Muslumanlara hizmet, Rabbime hizmettir" dedi.', hisse: 'Ozgurluk, nefsin degil; kalbin ozgurlugudur. Kul, Rabbine kul olunca ozgur olur.', anahtarKelimeler: ['Bilal', 'Hicret', 'Hizmet'], ikon: Icons.favorite_rounded, renk: Color(0xFFB71C1C)),
  Kissa(baslik: 'Habbab bin Eret (r.a.) ve Sabir', kaynak: 'Buhari, Menakib, 23', metin: 'Habbab bin Eret (r.a.), koleydi. Islama girdiginde efendisi onu atesle iskence etti. Bir gun sahabiler uzuldu: "Ya Resulullah, ne zaman zafer?" dediler. Peygamberimiz (s.a.v.): "Sizden onceki ummetler, vucutlari testereyle bicilirdi, yine imanlarindan donmezlerdi. Yemin olsun, bu din tamamlanacak" buyurdu. Habbab (r.a.) yillarca sabretti. Sonunda zafer geldi. Bedir`de, Uhud`da savasti. Kufe`ye vali oldu.', hisse: 'Sabir, en zor anda bile umidi korumaktir. Zafer, sabrin oduludur.', anahtarKelimeler: ['Habbab', 'Sabir', 'Zafer'], ikon: Icons.hourglass_bottom_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Ebu Zer (r.a.) ve Zuhd', kaynak: 'Buhari, Menakib, 26', metin: 'Ebu Zer (r.a.), Islama giren ilk sahabilerden. Kabilesinden ilk musluman oldu. Malini, mulkunu birakti. Bir gun Peygamberimiz (s.a.v.) ona: "Ey Ebu Zer, sen zayifsin, ise dayanamazsin. Bu is bir emanettir" buyurdu. Ebu Zer (r.a.): "Ben Rabbime kul olmayi, kullara emir olmaya tercih ederim" dedi. Halife Osman (r.a.) devrinde Rabze`ye surgun edildi. Orada yalniz yasadi. Vefat ettiginde yalnizdi.', hisse: 'Zuhd, dunyadan el etek cekmek degil; kalbi dunyadan kurtarmaktir.', anahtarKelimeler: ['Ebu Zer', 'Zuhd', 'Kanaat'], ikon: Icons.local_florist_rounded, renk: Color(0xFF2FAE7F)),
  Kissa(baslik: 'Talha bin Ubeydullah (r.a.) ve Feda', kaynak: 'Tirmizi, Menakib, 15', metin: 'Talha bin Ubeydullah (r.a.), Uhud savasinda Peygamberimizi (s.a.v.) vucuduyla siper etti. Bir ok eline saplandi; cekmedi, Peygamberimizi (s.a.v.) korudu. Oku cektiginde parmagi koptu. Yillarca sakat kaldi. Bir gun birisi ona: "Uhud`da ne kadar yaralandin?" dedi. Talha (r.a.): "Bir parmagimi kaybettim. Yuz parmagim olsaydi, hepsini Peygamberimiz (s.a.v.) icin verirdim" dedi.', hisse: 'Fedakarlik, hesaplamadan yapilir. Cennet, bedeli odenmis bir yerdir.', anahtarKelimeler: ['Talha', 'Feda', 'Uhud'], ikon: Icons.bloodtype_rounded, renk: Color(0xFFB71C1C)),
  Kissa(baslik: 'Zubeyr bin Avvam (r.a.) ve Cesaret', kaynak: 'Buhari, Fedail, 13', metin: 'Zubeyr bin Avvam (r.a.), Islam`in ilk kilic cekenidir. Mekke`de musluman oldugunda, müsrikler onu yakalamaya calisti. Zubeyr (r.a.) kilicini cekti, kendini korudu. Habesistan`a hicret etti. Butun savaslara katildi. Yaslandiginda bile savasa gitti. Bir gun oglu ona: "Baba, sen yaslandin, artik evde otur" dedi. Zubeyr (r.a.): "Yasliyim ama kalbim genc. Savas, kalbin isidir" dedi.', hisse: 'Cesaret, kasla degil; kalple olur. Yas, cesareti durdurmaz.', anahtarKelimeler: ['Zubeyr', 'Cesaret', 'Kilic'], ikon: Icons.sports_martial_arts_rounded, renk: Color(0xFF0A1F44)),
  Kissa(baslik: 'Ammar bin Yasir (r.a.) ve Iskence', kaynak: 'Buhari, Menakib, 20', metin: 'Ammar bin Yasir (r.a.), Islama ilk girenlerden. Annesi Sumeyye, ilk sehiddir. Babasi Yasir de sehid edildi. Ammar (r.a.), iskence altinda "Mekke putlarini" soylemeye mecbur birakildi. Aglaya aglaya Peygamberimize (s.a.v.) geldi. Peygamberimiz (s.a.v.): "Kalbin ne diyor?" buyurdu. "Iman dolu" dedi Ammar (r.a.). Peygamberimiz (s.a.v.): "O halde uzulme, onlar seni dininden cikaramiyor" buyurdu.', hisse: 'Zorlama altinda soylenen soz, kalptekini degistirmez. Allah, kalbe bakar.', anahtarKelimeler: ['Ammar', 'Iskence', 'Iman'], ikon: Icons.shield_rounded, renk: Color(0xFFB71C1C)),
  Kissa(baslik: 'Hz. Omer (r.a.) ve Halifelik', kaynak: 'Buhari, Fedail, 27', metin: 'Hz. Omer (r.a.), halife oldugunda minbere cikti: "Ey insanlar! Ben sizin en hayirliniz degilim. Dogru soylersem bana yardim edin, yanlis yaparsam beni duzeltin" dedi. On yil halifelik yapti. Iran`i, Şam`i, Misir`i, Kudus`u fethetti. Niler`in actigi kanallari tamir etti. Vefat ettiginde Medine`de bir yabanci tarafindan sehid edildi. Kani, mushafin uzerine akti.', hisse: 'Liderlik, emretmek degil; halka hizmet etmektir.', anahtarKelimeler: ['Omer', 'Hilafet', 'Adalet'], ikon: Icons.emoji_events_rounded, renk: Color(0xFFC9A961)),
];